using System.Net;
using System.Net.Http.Json;
using Xunit;

namespace Tests;

public class R1_ProtocolSchemeTests : IClassFixture<CustomWebApplicationFactory>
{
    private readonly CustomWebApplicationFactory _factory;

    public R1_ProtocolSchemeTests(CustomWebApplicationFactory factory)
    {
        _factory = factory;
    }

    [Fact]
    public async Task R1_Shorten_ValidHttpsScheme_ReturnsCreated()
    {
        var client = _factory.CreateClient();
        var payload = new CreateLinkRequest
        {
            DestinationUrl = "https://example.com/page",
            Url = "https://example.com/page"
        };

        var response = await client.PostAsJsonAsync("/api/links", payload);

        Assert.Equal(HttpStatusCode.Created, response.StatusCode);
        var body = await response.Content.ReadFromJsonAsync<CreateLinkResponse>();
        Assert.NotNull(body);
        Assert.False(string.IsNullOrWhiteSpace(body.EffectiveId));
    }

    [Theory]
    [InlineData("ftp://example.com")]
    [InlineData("javascript:alert(1)")]
    [InlineData("data:text/plain;base64,SGVsbG8=")]
    [InlineData("file:///etc/passwd")]
    public async Task R1_Shorten_UnsupportedSchemes_ReturnsBadRequest(string invalidUrl)
    {
        var client = _factory.CreateClient();
        var payload = new CreateLinkRequest
        {
            DestinationUrl = invalidUrl,
            Url = invalidUrl
        };

        var response = await client.PostAsJsonAsync("/api/links", payload);

        Assert.Equal(HttpStatusCode.BadRequest, response.StatusCode);
        var content = await response.Content.ReadAsStringAsync();
        Assert.NotEmpty(content);
    }
}
