    {
        using var factory = new CustomWebApplicationFactory();
        var client = factory.CreateClient(new Microsoft.AspNetCore.Mvc.Testing.WebApplicationClientOptions
        {
            AllowAutoRedirect = false
        });

        // Create link
        var createRes = await client.PostAsJsonAsync("/api/links", new CreateLinkRequest
        {
            DestinationUrl = "https://example.com/privacy-test",
            Url = "https://example.com/privacy-test"
        });
        Assert.Equal(HttpStatusCode.Created, createRes.StatusCode);
        var link = await createRes.Content.ReadFromJsonAsync<CreateLinkResponse>();
        Assert.NotNull(link);

        // Visit link with sensitive Client IP and recognizable User-Agent
        const string sensitiveClientIp = "203.0.113.199";
        const string uniqueUserAgent = "PrivacyVerificationAgent/9.9.9 (UniqueSecretBrowserIdentifier)";

        using var req = new HttpRequestMessage(HttpMethod.Get, $"/r/{link.EffectiveId}");
        req.Headers.Add("X-Forwarded-For", sensitiveClientIp);
        req.Headers.Add("User-Agent", uniqueUserAgent);
        req.Headers.Referrer = new Uri("https://partner.com/query?token=secret123");

        var visitRes = await client.SendAsync(req);
        Assert.Equal(HttpStatusCode.TemporaryRedirect, visitRes.StatusCode);

        // Check insights to ensure referrer path/query/secrets are stripped and domain only is retained
        var insightsRes = await client.GetAsync($"/api/links/{link.EffectiveId}/insights");
        var insightsContent = await insightsRes.Content.ReadAsStringAsync();

        Assert.DoesNotContain(sensitiveClientIp, insightsContent);
        Assert.DoesNotContain(uniqueUserAgent, insightsContent);
        Assert.DoesNotContain("secret123", insightsContent);

        // Read the SQLite database file directly from disk to verify raw persistence
        if (File.Exists(factory.DatabaseFilePath))
        {
            var dbBytes = await File.ReadAllBytesAsync(factory.DatabaseFilePath);
            var dbString = System.Text.Encoding.Latin1.GetString(dbBytes);

            Assert.DoesNotContain(sensitiveClientIp, dbString);
            Assert.DoesNotContain(uniqueUserAgent, dbString);
            Assert.DoesNotContain("secret123", dbString);
        }
    }
}
