    public async Task R9_HealthCheck_Returns200Ok()
    {
        var client = _factory.CreateClient();
        var response = await client.GetAsync("/healthz");

        Assert.Equal(HttpStatusCode.OK, response.StatusCode);
        var body = await response.Content.ReadAsStringAsync();
        Assert.NotEmpty(body);
    }

    [Fact]
    public async Task R9_Telemetry_TracksSecurityRejections()
    {
        var client = _factory.CreateClient();

        // 1. Read baseline telemetry
        var baselineRes = await client.GetAsync("/api/telemetry");
        Assert.Equal(HttpStatusCode.OK, baselineRes.StatusCode);
        var initialTelemetry = await baselineRes.Content.ReadFromJsonAsync<TelemetryResponse>();
        long initialSsrf = initialTelemetry?.SsrfBlocks ?? 0;
        long initialDenylist = initialTelemetry?.DenylistBlocks ?? 0;
        long initialTotalSecurity = initialTelemetry?.SecurityRejections ?? (initialSsrf + initialDenylist);

        // 2. Trigger SSRF block
        var ssrfRes = await client.PostAsJsonAsync("/api/links", new CreateLinkRequest
        {
            DestinationUrl = "http://127.0.0.1/forbidden",
            Url = "http://127.0.0.1/forbidden"
        });
        Assert.Equal(HttpStatusCode.BadRequest, ssrfRes.StatusCode);

        // 3. Trigger denylist block
        var denylistRes = await client.PostAsJsonAsync("/api/links", new CreateLinkRequest
        {
            DestinationUrl = "https://malicious-domain.com/evil",
            Url = "https://malicious-domain.com/evil"
        });
        Assert.Equal(HttpStatusCode.BadRequest, denylistRes.StatusCode);

        // 4. Verify updated telemetry
        var afterRes = await client.GetAsync("/api/telemetry");
        Assert.Equal(HttpStatusCode.OK, afterRes.StatusCode);
        var afterTelemetry = await afterRes.Content.ReadFromJsonAsync<TelemetryResponse>();
        Assert.NotNull(afterTelemetry);

        long afterSsrf = afterTelemetry.SsrfBlocks;
        long afterDenylist = afterTelemetry.DenylistBlocks;
        long afterTotal = afterTelemetry.SecurityRejections > 0
            ? afterTelemetry.SecurityRejections
            : (afterSsrf + afterDenylist);

        Assert.True(afterTotal > initialTotalSecurity || afterSsrf > initialSsrf || afterDenylist > initialDenylist,
            "Telemetry security rejection counters must be incremented following SSRF or denylist blocks.");
    }
}
