      "content": "using System;
using System.Collections.Generic;
using System.IO;
using Microsoft.AspNetCore.Hosting;
using Microsoft.AspNetCore.Mvc.Testing;
using Microsoft.Extensions.Configuration;

namespace Tests;

public class CustomWebApplicationFactory : WebApplicationFactory<Program>
{
    private readonly string _dbFilePath;
    private readonly Dictionary<string, string?> _customConfig;

    public CustomWebApplicationFactory(Dictionary<string, string?>? customConfig = null)
    { 
        _dbFilePath = Path.Combine(Path.GetTempPath(), $"linkshortener_{Guid.NewGuid():N}.db");
        _customConfig = customConfig ?? new Dictionary<string, string?>();
    }

    public string DatabaseFilePath => _dbFilePath;

    protected override void ConfigureWebHost(IWebHostBuilder builder)
    {
        builder.ConfigureAppConfiguration((context, config) =>
        {
            var dict = new Dictionary<string, string?>
            {
                ["ConnectionStrings:DefaultConnection"] = $"Data Source={_dbFilePath}",
                ["ConnectionStrings:Sqlite"] = $"Data Source={_dbFilePath}",
                ["Database:ConnectionString"] = $"Data Source={_dbFilePath}",
                ["Denylist:BlockedDomains:0"] = "malicious-domain.com",
                ["Denylist:BlockedDomains:1"] = "phishing-site.org",
                ["RateLimiting:PermitLimit"] = "5",
                ["RateLimiting:WindowSeconds"] = "60"
            };

            foreach (var kv in _customConfig)
            {
                dict[kv.Key] = kv.Value;
            }

            config.AddInMemoryCollection(dict);
        });
    }

    protected override void Dispose(bool disposing)
    {
        base.Dispose(disposing);
        if (disposing && File.Exists(_dbFilePath))
        {
            try
            {
                File.Delete(_dbFilePath);
            }
            catch
            {
                // Ignore cleanup lock issues in temporary directory
            }
        }
    }
}
