using System.Net;
using System.Net.Http.Json;
using Microsoft.AspNetCore.Mvc.Testing;
using Xunit;

namespace Tests;

public class R4_ExpirationTests : IClassFixture<CustomWebApplicationFactory>
{
    private readonly CustomWebApplicationFactory _factory;

    public R4_ExpirationTests(CustomWebApplicationFactory factory)
    {
        _factory = factory;
    }

    [Fact]
    public async Task R4_Shorten_DefaultExpiration_Sets90Days()
    {
        var client = _factory.CreateClient();
        var beforeCreation = DateTimeOffset.UtcNow.ToUnixTimeSeconds();

        var payload = new CreateLinkRequest
        {
            DestinationUrl = "https://example.com/default-expiry",
            Url = "https://example.com/default-expiry"
        };

        var response = await client.PostAsJsonAsync("/api/links", payload);
        Assert.Equal(HttpStatusCode.Created, response.StatusCode);

        var created = await response.Content.ReadFromJsonAsync<CreateLinkResponse>();
        Assert.NotNull(created);

        long expected90DaysSeconds = 90L * 24 * 60 * 60; // 7,776,000 seconds
        long diff = created.ExpiresAtEpochUtc - created.CreatedAtEpochUtc;

        // Allow a slight delta of +/- 5 seconds for execution timing
        Assert.InRange(diff, expected90DaysSeconds - 5, expected90DaysSeconds + 5);
        Assert.True(created.CreatedAtEpochUtc >= beforeCreation - 2);
    }

    [Fact]
    public async Task R4_Shorten_CustomExpiration_SetsExplicitDuration()
    {
        var client = _factory.CreateClient();

        var payload = new CreateLinkRequest
        {
            DestinationUrl = "https://example.com/custom-expiry",
            Url = "https://example.com/custom-expiry",
            ExpiresInDays = 14,
            ExpiresInSeconds = 14 * 86400
        };

        var response = await client.PostAsJsonAsync("/api/links", payload);
        Assert.Equal(HttpStatusCode.Created, response.StatusCode);

        var created = await response.Content.ReadFromJsonAsync<CreateLinkResponse>();
        Assert.NotNull(created);

        long expected14DaysSeconds = 14L * 86400;
        long diff = created.ExpiresAtEpochUtc - created.CreatedAtEpochUtc;
        Assert.InRange(diff, expected14DaysSeconds - 5, expected14DaysSeconds + 5);
    }

    [Fact]
    public async Task R4_AccessExpiredLink_ReturnsGoneOrNotFoundAndNoRedirect()
    {
        var client = _factory.CreateClient(new WebApplicationFactoryClientOptions
        {
            AllowAutoRedirect = false
        });

        var payloadPast = new CreateLinkRequest
        {
            DestinationUrl = "https://example.com/expired-target",
            Url = "https://example.com/expired-target",
            ExpiresInSeconds = -10,
            ExpiresInDays = -1
        };

        var postRes = await client.PostAsJsonAsync("/api/links", payloadPast);
        string? expiredId = null;

        if (postRes.StatusCode == HttpStatusCode.Created)
        {
            var link = await postRes.Content.ReadFromJsonAsync<CreateLinkResponse>();
            expiredId = link?.EffectiveId;
        }
        else
        {
            // If API enforces positive duration on creation, create normally then artificially update DB
            var validPayload = new CreateLinkRequest
            {
                DestinationUrl = "https://example.com/expired-target-valid",
                Url = "https://example.com/expired-target-valid"
            };
            var createRes = await client.PostAsJsonAsync("/api/links", validPayload);
            var link = await createRes.Content.ReadFromJsonAsync<CreateLinkResponse>();
            expiredId = link?.EffectiveId;

            try
            {
                using var connection = new Microsoft.Data.Sqlite.SqliteConnection($"Data Source={_factory.DatabaseFilePath}");
                await connection.OpenAsync();
                using var cmd = connection.CreateCommand();
                cmd.CommandText = $"UPDATE ShortenedLinks SET ExpiresAtEpochUtc = 1 WHERE Id = '{expiredId}';";
                await cmd.ExecuteNonQueryAsync();
            }
            catch
            {
                try
                {
                    using var connection = new Microsoft.Data.Sqlite.SqliteConnection($"Data Source={_factory.DatabaseFilePath}");
                    await connection.OpenAsync();
                    using var cmd = connection.CreateCommand();
                    cmd.CommandText = $"UPDATE ShortenedLink SET ExpiresAtEpochUtc = 1 WHERE Id = '{expiredId}';";
                    await cmd.ExecuteNonQueryAsync();
                }
                catch
                {
                    // Ignore if direct DB update is not possible
                }
            }
        }

        Assert.NotNull(expiredId);
        var getRes = await client.GetAsync($"/r/{expiredId}");

        // Requirement states HTTP 410 Gone (or HTTP 404 Not Found) and does not perform redirect
        Assert.True(getRes.StatusCode == HttpStatusCode.Gone || getRes.StatusCode == HttpStatusCode.NotFound,
            $"Expected 410 Gone or 404 Not Found but received {getRes.StatusCode}");
        Assert.Null(getRes.Headers.Location);
    }
}
