    [Fact]
    public async Task R5_Shorten_WithinQuota_Returns201Created()
    {
        using var customFactory = new CustomWebApplicationFactory(new Dictionary<string, string?>
        {
            ["RateLimiting:PermitLimit"] = "100"
        });
        var client = customFactory.CreateClient();
        client.DefaultRequestHeaders.Add("X-Forwarded-For", "198.51.100.1");

        var payload = new CreateLinkRequest
        {
            DestinationUrl = "https://example.com/under-quota",
            Url = "https://example.com/under-quota"
        };

        var response = await client.PostAsJsonAsync("/api/links", payload);
        Assert.Equal(HttpStatusCode.Created, response.StatusCode);
    }

    [Fact]
    public async Task R5_Shorten_ExceedingQuota_Returns429TooManyRequestsWithRetryAfterHeader()
    {
        using var tightLimitFactory = new CustomWebApplicationFactory(new Dictionary<string, string?>
        {
            ["RateLimiting:PermitLimit"] = "2",
            ["RateLimiting:WindowSeconds"] = "60"
        });

        var client = tightLimitFactory.CreateClient();
        var testClientIp = $"203.0.113.{Random.Shared.Next(10, 250)}";
        client.DefaultRequestHeaders.Add("X-Forwarded-For", testClientIp);

        bool hit429 = false;
        HttpResponseMessage? rateLimitedResponse = null;

        for (int i = 0; i < 15; i++)
        {
            var payload = new CreateLinkRequest
            {
                DestinationUrl = $"https://example.com/rate-test-{i}",
                Url = $"https://example.com/rate-test-{i}"
            };

            var res = await client.PostAsJsonAsync("/api/links", payload);
            if (res.StatusCode == HttpStatusCode.TooManyRequests)
            {
                hit429 = true;
                rateLimitedResponse = res;
                break;
            }
        }

        Assert.True(hit429, "Expected HTTP 429 Too Many Requests when exceeding rate limit.");
        Assert.NotNull(rateLimitedResponse);
        Assert.Equal(HttpStatusCode.TooManyRequests, rateLimitedResponse.StatusCode);
        Assert.True(rateLimitedResponse.Headers.Contains("Retry-After") || rateLimitedResponse.Headers.RetryAfter != null,
            "HTTP 429 response must contain a 'Retry-After' header.");
    }
}
