using Microsoft.AspNetCore.Mvc.Testing;
using Xunit;

namespace Tests;

public class R7_AnalyticsTests : IClassFixture<CustomWebApplicationFactory>
{
    private readonly CustomWebApplicationFactory _factory;

    public R7_AnalyticsTests(CustomWebApplicationFactory factory)
    {
        _factory = factory;
    }

    [Fact]
    public async Task R7_Analytics_AggregatesClicksAndReferrerDomain()
    {
        var client = _factory.CreateClient(new WebApplicationFactoryClientOptions
        {
            AllowAutoRedirect = false
        });

        var createRes = await client.PostAsJsonAsync("/api/links", new CreateLinkRequest
        {
            DestinationUrl = "https://example.com/target-analytics",
            Url = "https://example.com/target-analytics"
        });

        Assert.Equal(HttpStatusCode.Created, createRes.StatusCode);
        var link = await createRes.Content.ReadFromJsonAsync<CreateLinkResponse>();
        Assert.NotNull(link);
        var id = link.EffectiveId;

        // 3 visits from news.ycombinator.com
        for (int i = 0; i < 3; i++)
        {
            using var req = new HttpRequestMessage(HttpMethod.Get, $"/r/{id}");
            req.Headers.Referrer = new Uri("https://news.ycombinator.com/item?id=123");
            var res = await client.SendAsync(req);
            Assert.Equal(HttpStatusCode.TemporaryRedirect, res.StatusCode);
        }

        // 2 visits direct (no Referer header)
        for (int i = 0; i < 2; i++)
        {
            using var req = new HttpRequestMessage(HttpMethod.Get, $"/r/{id}");
            var res = await client.SendAsync(req);
            Assert.Equal(HttpStatusCode.TemporaryRedirect, res.StatusCode);
        }

        var insightsRes = await client.GetAsync($"/api/links/{id}/insights");
        Assert.Equal(HttpStatusCode.OK, insightsRes.StatusCode);

        var insights = await insightsRes.Content.ReadFromJsonAsync<InsightsResponse>();
        Assert.NotNull(insights);
        Assert.Equal(5, insights.TotalClicks);

        var dailyList = insights.DailyClicks ?? insights.DailyTrend ?? new();
        Assert.NotEmpty(dailyList);
        var totalDailyClicks = dailyList.Sum(d => d.EffectiveCount);
        Assert.Equal(5, totalDailyClicks);

        var referrers = insights.TopReferrers ?? insights.Referrers ?? new();
        Assert.NotEmpty(referrers);

        var hnReferrer = referrers.FirstOrDefault(r => r.EffectiveDomain.Contains("news.ycombinator.com", StringComparison.OrdinalIgnoreCase));
        Assert.NotNull(hnReferrer);
        Assert.Equal(3, hnReferrer.EffectiveCount);
    }

    [Fact]
    public async Task R7_Analytics_NonExistentLink_ReturnsNotFound()
    {
        var client = _factory.CreateClient();
        var response = await client.GetAsync("/api/links/nonexistenttoken/insights");
        Assert.Equal(HttpStatusCode.NotFound, response.StatusCode);
    }
}
